targets.expr:
sum(
  increase(canvas_connect_interview_rooms_created_total[$__range])
  * on(exported_job, exported_instance) group_left(deployment_environment_name, service_version)
  target_info{deployment_environment_name=~"$environment", service_version=~"$version"}
)

sum(
  canvas_connect_interview_participants_active
  * on(exported_job, exported_instance) group_left(deployment_environment_name, service_version)
  target_info{deployment_environment_name=~"$environment", service_version=~"$version"}
)

sum(
  increase(canvas_connect_canvas_elements_created_total[$__range])
  * on(exported_job, exported_instance) group_left(deployment_environment_name, service_version)
  target_info{deployment_environment_name=~"$environment", service_version=~"$version"}
)

sum(
  increase(canvas_connect_component_creation_failures_total[$__range])
  * on(exported_job, exported_instance) group_left(deployment_environment_name, service_version)
  target_info{deployment_environment_name=~"$environment", service_version=~"$version"}
)

sum by (reason) (
  rate(canvas_connect_component_creation_failures_total[$__rate_interval])
  * on(exported_job, exported_instance) group_left(deployment_environment_name, service_version)
  target_info{deployment_environment_name=~"$environment", service_version=~"$version"}
)
